
<div
  class="dialog"
  :style="{ display: value ? 'flex' : 'none' }"
  @click.self="$emit('input', false)"
>
  <div
    class="dialog-body"
    style="overflow-y: auto;"
    :style="{'max-height': maxHeight}"
  >
    <div class="dialog-header" @click="$emit('input', false)">
      <slot name="header"></slot>
    </div>
    <div class="dialog-content">
      <slot></slot>
    </div>
  </div>
</div>
